from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
BASE='''> **Estado documental:** protótipo funcional digital. A pulseira física não foi construída nem testada. Dados da demonstração são sintéticos; registros de piloto nesta versão permanecem apenas no navegador e não constituem, por si, avaliação institucional realizada.\n\n'''

sections={
'01-meta-01-pesquisa-design':[
('01_PLANO_EXECUCAO','Planejamento da Meta 1','Mapear público, linguagem, trilhas, acessibilidade e critérios técnicos. Entregas: requisitos, catálogo pedagógico, fluxos e arquitetura. Revisar com a equipe antes de uso em campo.'),
('02_BANCO_VOCABULARIO','Banco de vocabulário inicial','O vocabulário em `src/data.ts` possui 14 categorias funcionais e foi criado para desenvolvimento. Palavras como UBS, ônibus, água e documentação apoiam atividades cotidianas. Não há alegação de coleta em entrevistas.'),
('03_FLUXO_INTERACAO','Fluxo de interação','A participante escolhe uma trilha, fornece entrada por texto ou voz quando disponível, recebe uma resposta do motor local e pode repetir ou concluir. Para piloto: apresentação → consentimento → tutorial → experiência → avaliação → agradecimento.'),
('04_REQUISITOS_FUNCIONAIS','Requisitos funcionais','RF01: escolher trilha; RF02: responder por texto; RF03: tentar voz quando suportada; RF04: ouvir resposta quando suportado; RF05: registrar sessão anônima; RF06: concluir atividade; RF07: preencher SUS opcional; RF08: visualizar métricas; RF09: separar dados sintéticos; RF10: consultar mentoria.'),
('05_REQUISITOS_NAO_FUNCIONAIS','Requisitos não funcionais','RNF01: primeira experiência acessível em tela pequena; RNF02: contraste e controles grandes; RNF03: funcionamento local sem backend; RNF04: conteúdo disponível offline após primeira carga; RNF05: privacidade por padrão; RNF06: fallback textual; RNF07: persistência IndexedDB.'),
('06_ARQUITETURA_PEDAGOGICA','Arquitetura pedagógica','Dez trilhas com atividades curtas de identificação, leitura e aplicação no cotidiano. Cada atividade inclui objetivo, prompt, respostas esperadas e feedback. A progressão local usa número de conclusões: nível 1 até duas, nível 2 de três a seis, nível 3 a partir de sete.'),
('07_ARQUITETURA_TECNICA','Arquitetura técnica','React e TypeScript apresentam os fluxos; `src/core.ts` contém o motor determinístico; `src/data.ts` fornece conteúdo; `src/storage.ts` define adapter IndexedDB; service worker armazena assets locais. A interface `PersistenceAdapter` permite substituição futura por armazenamento remoto.'),
('08_DIARIO_BORDO','Diário de bordo da Meta 1','Registro técnico inicial: requisitos e trilhas foram derivados da proposta institucional. Pesquisa com participantes e validação comunitária permanecem pendentes. Acrescentar datas, responsáveis e decisões reais conforme ocorrerem.'),
('09_RELATORIO_META_01','Relatório da Meta 1','Foram preparados requisitos, fluxos e arquitetura do protótipo digital. O conteúdo é inicial de desenvolvimento e requer revisão pedagógica e validação com participantes antes de qualquer afirmação de eficácia.'),
('10_CONCLUSAO_META_01','Conclusão da Meta 1','O planejamento técnico e pedagógico necessário ao demonstrador está documentado. A validação participativa da abordagem permanece trabalho futuro.')],
'02-meta-02-prototipo-testes':[
('01_DESCRICAO_PROTOTIPO','Descrição do protótipo digital','Aplicação web instalável com interação textual, recursos de voz dependentes do navegador, dez trilhas, sessões locais, mentoria, painel e diagnósticos. A pulseira exibida é representação conceitual.'),
('02_ARQUITETURA_SOFTWARE','Arquitetura de software','Camadas: interface React → motor local `src/core.ts` → catálogo `src/data.ts` e persistência `src/storage.ts`. O motor não consulta serviços externos. O PWA armazena assets do mesmo domínio via service worker.'),
('03_MOTOR_INTERACAO_LOCAL','Motor de interação local','A entrada é normalizada, comparada a expressões e palavras-chave, associada a uma intent e, quando cabível, a uma atividade. A resposta é determinística e baseada em conteúdo previamente escrito. Não há LLM. A função `respond` aceita contexto, permitindo trocar o motor no futuro sem redesenhar a interface.'),
('04_PLANO_TESTES','Plano de testes do protótipo digital','Executar `npm run typecheck`, `npm run test`, `npm run build` e `npm run test:e2e`. Verificar entrada textual, resposta correta e incorreta, conclusão, consentimento, SUS, segregação de dados, persistência, responsividade e uso offline. Registrar ambiente, saída e artefatos.'),
('05_TESTE_FUNCIONAL','Teste funcional do protótipo digital','Cenários automatizados estão em `src/core.test.ts` e `e2e/flows.spec.ts`. O resultado real de execução deve ser consultado em `docs/qa/QA_REPORT.md` e `FINAL_QA_REPORT.md`; não se inferem testes de hardware.'),
('06_TESTE_USABILIDADE_TECNICA','Teste técnico de usabilidade','A inspeção técnica cobre tamanho de controles, navegação móvel, leitura, contraste, estados visíveis e fallback textual. Não substitui teste com participantes. Registrar observações reais e correções neste arquivo ao executar a inspeção.'),
('07_TESTE_OFFLINE','Teste offline do protótipo digital','Após abrir a aplicação online, o service worker instala cache de shell e assets visitados. Para testar: carregar, atualizar, ativar offline nas ferramentas do navegador e recarregar. A voz de entrada pode depender de serviços do navegador e não é garantida offline.'),
('08_RESULTADOS_TESTES','Resultados de testes','Os resultados verificados e limitações estão em `docs/qa/QA_REPORT.md`. Atualizar este documento apenas com saídas de execução observadas.'),
('09_DIARIO_BORDO','Diário de bordo da Meta 2','Desenvolvimento do protótipo digital: motor, catálogo, IndexedDB, PWA, telas e testes. Preencher registros de execução com data e responsável reais quando ocorrerem.'),
('10_RELATORIO_META_02','Relatório da Meta 2','A entrega da Meta 2 nesta fase é software executável e testes técnicos do protótipo digital. A construção, montagem e validação física da pulseira não ocorreram.'),
('11_CONCLUSAO_META_02','Conclusão da Meta 2','O demonstrador permite avaliar fluxos computacionais e pedagógicos em software. Testes embarcados dependem de futura aquisição e construção do hardware.')],
'03-meta-03-piloto':[
('01_PLANO_PILOTO','Plano de piloto','Realizar posteriormente recrutamento e consentimento conforme procedimentos institucionais. Preparar navegador, explicar retenção local, conduzir atividades, coletar avaliação opcional e exportar/registrar resultados apenas após definir governança de dados. Nenhum piloto real é reivindicado aqui.'),
('02_TERMO_PARTICIPACAO_MODELO','Modelo de termo de participação','Finalidade: observar usabilidade do protótipo digital. Participação voluntária; desistência livre; evitar dados pessoais no campo de texto. Armazenamento nesta versão: navegador local, sem transmissão. Responsáveis e contatos institucionais devem ser preenchidos e aprovados antes do uso real.'),
('03_ROTEIRO_SESSAO','Roteiro de sessão','Apresentar objetivo e limites → explicar consentimento → oferecer tutorial → permitir escolha de trilha → observar dificuldades sem induzir respostas → concluir → pedir feedback e SUS opcional → agradecer. Cronometrar e registrar apenas dados autorizados.'),
('04_INSTRUMENTO_FEEDBACK','Instrumento de feedback','Perguntas propostas: O que ficou fácil? O que dificultou? A leitura e o áudio ajudaram? O que mudaria? O campo livre da aplicação guarda texto somente no navegador; orientar a não inserir dados sensíveis.'),
('05_QUESTIONARIO_SUS','Questionário SUS','A interface usa os dez itens da System Usability Scale, em escala de 1 a 5. Itens ímpares contribuem com resposta menos 1; pares com 5 menos resposta. A soma é multiplicada por 2,5, produzindo 0–100. Respostas incompletas não são pontuadas. O resultado aparece somente no painel.'),
('06_PLANO_ANALISE','Plano de análise','Separar registros reais locais de dados sintéticos. Calcular sessões, tentativas, conclusões, erros, duração média, distribuição por trilha e SUS apenas sobre questionários completos. Não equiparar códigos de sessão a pessoas únicas nem inferir aprendizagem sem desenho avaliativo.'),
('07_DADOS_SINTETICOS_DEMONSTRACAO','Dados sintéticos da demonstração','A função `makeSyntheticSessions` gera 25 sessões sintéticas variadas e identificadas com `synthetic: true`. A tela do painel permite gerar e limpar somente essas sessões. São simulações de interface, sem participação ou atendimento realizado.'),
('08_MODELO_RELATORIO_PILOTO','Modelo de relatório de piloto','Preencher após piloto autorizado: período [ ], local [ ], critérios de recrutamento [ ], número de participantes reais [ ], procedimento [ ], resultados [ ], limitações [ ], evidências [ ]. Não usar os dados sintéticos como resultados reais.'),
('09_DIARIO_BORDO','Diário de bordo da Meta 3','Modelo para registros futuros: data [ ], responsável [ ], evento [ ], participantes com códigos anônimos [ ], intercorrências [ ], evidência [ ]. Sem entradas reais nesta fase.'),
('10_CONCLUSAO_META_03_MODELO','Modelo de conclusão da Meta 3','Conclusão pendente de aplicação piloto real. O fluxo digital e dados sintéticos estão disponíveis para demonstração técnica.')],
'04-meta-04-mentoria':[
('01_PLANO_FORMACAO_MENTORA','Plano de formação','Sete módulos: projeto, alfabetização mediada, condução, inclusão, privacidade, feedback e resolução de problemas. Oficinas e certificação formal requerem execução institucional.'),
('02_GUIA_MENTORA','Guia da mentora','Acolher, explicar o protótipo digital, obter consentimento, oferecer texto como alternativa, observar sem responder pela participante, não pedir dados sensíveis e registrar feedback autorizado. Consultar `/mentora` para orientações de uso.'),
('03_ROTEIRO_OFICINA','Roteiro de oficina','Abertura e contexto (15 min); demonstração do fluxo (20 min); prática em duplas (30 min); acessibilidade e privacidade (20 min); dúvidas e avaliação (15 min). Tempos são proposta, não registro de oficina realizada.'),
('04_MATERIAL_FORMACAO','Material de formação','Módulo 1: limites do protótipo. 2: apoio à alfabetização sem infantilizar. 3: condução e consentimento. 4: recursos acessíveis. 5: proteção de dados. 6: observação e feedback. 7: recuperação de falhas e fallback textual.'),
('05_CHECKLIST_MENTORA','Checklist da mentora','Antes: dispositivo carregado, navegador compatível, explicação e consentimento. Durante: permitir escolha, confirmar compreensão, observar dificuldades. Depois: encerrar, agradecer, revisar registros locais e guardar evidências autorizadas.'),
('06_AVALIACAO_FORMACAO','Avaliação da formação','Modelo futuro: segurança para conduzir sessão [1–5], clareza do material [1–5], dúvidas pendentes [ ], melhoria proposta [ ]. Não há resultados de formação real registrados.'),
('07_DIARIO_BORDO','Diário de bordo da Meta 4','Modelo futuro: data [ ], módulo [ ], responsável [ ], participantes [ ], dificuldades [ ], evidências [ ]. O checklist na interface é demonstrativo e não comprova formação.'),
('08_RELATORIO_META_04_MODELO','Modelo de relatório da Meta 4','Descrever oficina real, participantes, materiais utilizados, avaliação e evidências quando ocorrer. Nesta fase existe apenas a área digital de apoio à mentora.'),
('09_CONCLUSAO_META_04_MODELO','Modelo de conclusão da Meta 4','A conclusão sobre formação efetiva depende de oficina institucional realizada e documentada.')],
'05-meta-05-disseminacao':[
('01_PLANO_DISSEMINACAO','Plano de disseminação','Preparar demonstração do software, vídeo de navegação, apresentação técnica e relato institucional. Toda publicação deve explicitar limites, origem sintética dos dados e ausência do wearable físico.'),
('02_RELATORIO_TECNICO','Relatório técnico','Arquitetura: aplicação React/TypeScript local, motor de regras, IndexedDB, PWA e testes automatizados. Evidências de execução devem vir de relatórios de QA e capturas verificadas.'),
('03_ROTEIRO_VIDEO_DEMONSTRATIVO','Roteiro de vídeo demonstrativo','Cena 1: identidade e objetivo. Cena 2: representação conceitual da pulseira, com aviso. Cena 3: trilhas e interação. Cena 4: piloto local e consentimento. Cena 5: mentora. Cena 6: painel com aviso de dados sintéticos. Encerrar com limitações.'),
('04_ROTEIRO_APRESENTACAO','Roteiro de apresentação','Slides propostos: contexto; problema; metas; protótipo digital; arquitetura; fluxo pedagógico; privacidade; demonstração; testes técnicos; limitações e próximos passos.'),
('05_ARTIGO_BASE','Artigo base','Título proposto: Prototipagem digital de uma interface educacional local para alfabetização funcional. Resumo, fundamentação, método, implementação, avaliação técnica, limites e próximos passos devem ser preenchidos com fontes e resultados verificados antes de submissão.'),
('06_RESUMO_EXPANDIDO','Resumo expandido','Objetivo: descrever o desenvolvimento de um demonstrador digital local. Método: arquitetura determinística, trilhas estruturadas e testes técnicos. Resultados: preencher somente com evidências verificadas. Limitação: sem hardware e sem avaliação com participantes nesta fase.'),
('07_PLANO_CONTINUIDADE','Plano de continuidade','Revisar conteúdo com educadoras e comunidade; definir protocolo e governança de piloto; realizar avaliação real; melhorar acessibilidade; planejar compra e desenvolvimento embarcado; avaliar sincronização remota optativa.'),
('08_RELATORIO_META_05','Relatório da Meta 5','O repositório contém base de documentação e materiais de disseminação. Publicações, apresentações e vídeo externo permanecem pendentes de realização e registro.'),
('09_CONCLUSAO_META_05','Conclusão da Meta 5','Há materiais preparatórios para sistematização e disseminação. Conclusão institucional depende de divulgação efetiva e evidência correspondente.')],
'encerramento':[
('01_MATRIZ_RASTREABILIDADE','Matriz de rastreabilidade','| Objetivo | Meta | Atividade | Requisito | Funcionalidade | Teste | Resultado | Evidência | Documento |\n|---|---|---|---|---|---|---|---|---|\n| Interação local | 2 | Motor | RF01–RF04 | `src/core.ts` | `src/core.test.ts` | Ver QA | QA_REPORT | Meta 2/03 |\n| Sessões | 2/3 | Registro | RF05 | `src/storage.ts` | E2E fluxo | Ver QA | QA_REPORT | Meta 3/01 |\n| SUS | 3 | Avaliação | RF07 | `calculateSUS` | Unitário/E2E | Ver QA | QA_REPORT | Meta 3/05 |\n| Mentoria | 4 | Apoio | RF10 | `/mentora` | E2E navegação | Ver QA | QA_REPORT | Meta 4/02 |\n| Indicadores | 5 | Sistematização | RF08–RF09 | `/dashboard` | E2E navegação | Ver QA | QA_REPORT | Meta 5/02 |'),
('02_MATRIZ_METAS_EVIDENCIAS','Matriz metas e evidências','Meta 1: requisitos e conteúdo em `docs/01-meta-01-pesquisa-design`. Meta 2: código e QA técnico. Meta 3: fluxo preparado; sem evidência de piloto real. Meta 4: área de mentoria; sem evidência de formação real. Meta 5: documentação base; divulgação externa não comprovada.'),
('03_INDICE_EVIDENCIAS','Índice de evidências','Consultar `evidence/EVIDENCE_INDEX.md`. Arquivos só são classificados como evidência após geração e verificação. Modelos e roteiros não são resultados.'),
('04_CONCLUSAO_PROJETO','Conclusão técnica nesta fase','O A.U.R.O.R.A. evoluiu da concepção para um protótipo funcional digital que permite examinar fluxos computacionais e pedagógicos. A conclusão institucional completa requer piloto, formação e disseminação reais.'),
('05_LICOES_APRENDIDAS','Lições aprendidas','Antecipar compras e avaliar risco de dependência de hardware; separar software de hardware; prototipar cedo; automatizar testes; projetar offline; considerar acessibilidade desde o início; documentar decisões e rastreabilidade; preservar privacidade; distinguir dados sintéticos e reais; planejar escalabilidade.'),
('06_LIMITACOES_E_TRABALHOS_FUTUROS','Limitações e trabalhos futuros','Não há pulseira física, teste embarcado, sincronização remota ou avaliação real nesta entrega. Voz depende do navegador e pode não funcionar offline. O conteúdo precisa de revisão pedagógica comunitária. Planejar hardware, validação ética e piloto autorizado.'),
('07_RESUMO_EXECUTIVO','Resumo executivo','Protótipo digital executável para interação educacional local com dez trilhas, registro anônimo no navegador, apoio à mentora, painel e demonstração sintética. Seu valor nesta etapa é técnico e preparatório; eficácia pedagógica exige avaliação real.'),
('08_RELATORIO_FINAL_BASE','Relatório final — base','O A.U.R.O.R.A. evoluiu da concepção para um protótipo funcional digital, permitindo implementar e avaliar tecnicamente a arquitetura computacional, os fluxos pedagógicos e os principais mecanismos de interação previstos. A implementação física do componente vestível permaneceu como etapa futura, em razão da impossibilidade de aquisição dos componentes dentro da janela operacional disponível. A estratégia reduziu riscos tecnológicos e amadureceu requisitos. Inserir aqui apenas resultados e evidências efetivamente obtidos.'),
('09_CHECKLIST_ENCERRAMENTO','Checklist de encerramento','[ ] Validar QA; [ ] revisar documentos; [ ] conferir rastreabilidade; [ ] identificar dados sintéticos; [ ] anexar evidências reais autorizadas; [ ] revisar limites; [ ] preencher SUAP com informações verificadas; [ ] aprovar relatório institucional.'),
('10_GUIA_PREENCHIMENTO_SUAP','Guia de preenchimento SUAP','Utilizar descrição fiel da entrega digital, indicar metas concluídas tecnicamente e pendências de piloto, formação e disseminação. Vincular arquivo, data e responsável de cada evidência. Não registrar simulação como atendimento ou hardware construído.'),
('11_PLANO_CAPTURA_FOTOS','Plano de captura de fotos','Fotos futuras de oficinas ou participantes exigem autorização e registro de origem, data e finalidade. Nesta fase não há fotos de participante ou hardware para anexar.'),
('12_PLANO_CAPTURA_SCREENSHOTS','Plano de captura de screenshots','O script `e2e/screenshots.spec.ts` captura rotas de produto. Antes da inclusão em relatório, executar, revisar os arquivos, remover dados pessoais e identificar telas com dados sintéticos.'),
('13_ANEXOS','Anexos','Anexar registros de QA, capturas, termos aprovados e materiais de oficina após criação e verificação. Não incluir placeholders como evidência de execução.')]
}

for directory,items in sections.items():
    target=ROOT/'docs'/directory
    target.mkdir(parents=True,exist_ok=True)
    for filename,title,body in items:
        (target/(filename+'.md')).write_text(f'# {title}\n\n'+BASE+body+'\n',encoding='utf-8')

for directory in ['00-governanca','arquitetura','requisitos','qa','evidencias','relatorios','artigo']:
    (ROOT/'docs'/directory).mkdir(parents=True,exist_ok=True)
for directory in ['meta-01','meta-02','meta-03','meta-04','meta-05','screenshots','tests','video','photos','exports']:
    path=ROOT/'evidence'/directory
    path.mkdir(parents=True,exist_ok=True)
    (path/'.gitkeep').touch()

(ROOT/'docs/00-governanca/CRITERIOS_DE_EVIDENCIA.md').write_text('# Governança de evidências\n\n'+BASE+'Cada alegação deve indicar implementação, simulação, teste técnico, avaliação real ou trabalho futuro. A ausência de evidência não deve ser substituída por dado sintético.\n',encoding='utf-8')
(ROOT/'docs/arquitetura/DECISAO_MOTOR_LOCAL.md').write_text('# Decisão: motor educacional local\n\n'+BASE+'A versão atual usa regras, intents e respostas explícitas. Esse desenho é auditável, previsível e funciona sem backend. Não se apresenta como modelo de linguagem ou inteligência artificial generativa. A função `respond(input, context)` e o adapter de persistência permitem substituir implementações no futuro.\n',encoding='utf-8')
(ROOT/'docs/requisitos/INDICE.md').write_text('# Índice de requisitos\n\nConsultar os arquivos 04 e 05 da Meta 1 e a matriz em `docs/encerramento/01_MATRIZ_RASTREABILIDADE.md`.\n',encoding='utf-8')
